exercises.answer:
SpotAllocator owns occupancy, ParkingService owns tickets, and FeePolicy owns pricing. Policy references must outlive the service. This single-threaded in-memory example does not implement concurrent allocation or persistence. A production ticket store can be extracted behind its own interface.

```cpp
#include <iostream>
#include <vector>
#include <algorithm>

enum class Vehicle { Car, Motorcycle };
struct Spot { Vehicle kind; bool occupied = false; };
struct Ticket { int id; int spot; int entered; bool active = true; };

class SpotAllocator {
    std::vector<Spot> spots{{Vehicle::Car}, {Vehicle::Motorcycle}};
public:
    int allocate(Vehicle kind) {
        for (int i = 0; i < static_cast<int>(spots.size()); ++i) {
            if (spots[i].kind == kind && !spots[i].occupied) {
                spots[i].occupied = true;
                return i;
            }
        }
        return -1;
    }
    void release(int spot) { spots[spot].occupied = false; }
};

struct FeePolicy {
    virtual int calculate(int hours) const = 0;
    virtual ~FeePolicy() = default;
};
struct HourlyFee : FeePolicy {
    int calculate(int hours) const override { return hours * 10; }
};
struct FlatFee : FeePolicy {
    int calculate(int) const override { return 15; }
};

class ParkingService {
    SpotAllocator allocator;
    std::vector<Ticket> tickets;
    const FeePolicy& policy;
public:
    explicit ParkingService(const FeePolicy& fee) : policy(fee) {}
    int enter(Vehicle kind, int hour) {
        int spot = allocator.allocate(kind);
        if (spot == -1) return -1;
        int id = static_cast<int>(tickets.size()) + 1;
        tickets.push_back({id, spot, hour});
        return id;
    }
    int exit(int id, int hour) {
        for (auto& ticket : tickets) {
            if (ticket.id == id && ticket.active && hour >= ticket.entered) {
                int fee = policy.calculate(hour - ticket.entered);
                ticket.active = false;
                allocator.release(ticket.spot);
                return fee;
            }
        }
        return -1;
    }
};

int main() {
    HourlyFee hourly;
    ParkingService lot(hourly);
    int car = lot.enter(Vehicle::Car, 9);
    std::cout << "Car ticket: " << car << '\n';
    std::cout << "Second car: " << lot.enter(Vehicle::Car, 9) << '\n';
    std::cout << "Motorcycle ticket: " << lot.enter(Vehicle::Motorcycle, 9) << '\n';
    std::cout << "Early exit: " << lot.exit(car, 8) << '\n';
    std::cout << "Car fee: " << lot.exit(car, 12) << '\n';
    std::cout << "Repeated exit: " << lot.exit(car, 13) << '\n';
    std::cout << "New car ticket: " << lot.enter(Vehicle::Car, 13) << '\n';
    FlatFee flat;
    ParkingService flatLot(flat);
    std::cout << "Flat fee: " << flatLot.exit(flatLot.enter(Vehicle::Car, 9), 12) << '\n';
}
